  "guide.household.inviteText": "इस 6 अक्षरें दा कोड परिवार दे सदस्यें कन्नै सांझा करो। ओह् Perovo च साइन इन करदे न, Profile च फैमिली मोड चालू करदे न, ते तुंदे कमरे च शामल होने आस्तै इस कोड गी दर्ज करदे न.",
