  "guide.household.shareText": "तुस फैसला करो के परिवार दे सदस्य केह् दिक्खी सकदे न। शेयर खर्चें गी टॉगल करो तां जे दुए गी तुंदे रोजमर्रा दे खर्चे गी दिक्खी सकै। अपनी प्रतिबद्धता सूची साझा करने लेई बिल दे नांऽ टॉगल करो।",
  "guide.household.outlookTitle": "घर दा नज़रिया",
