  "profileHub.scorePayOrder": "सुझाव दित्ता गेदा पे आर्डर",
  "profileHub.scorePayOrderHint": "नकद तंग होने पर पैह् ले ओवरड्यू ते उच्च ब्याज आह् ले बिल दा भुगतान करो।",
