  "profileHub.scoreFix.payFirstHint": "ओवरड्यू / उच्च-ब्याज वजन तेज़ी कन्नै साफ करदा ऐ।",
  "profileHub.scoreWhy.pressure.what": "मापदा ऐ जे तुंदी आमदनी दा किन्ना बिल ते ओवरड्यू आइटम च बंद ऐ।",
  "profileHub.scoreWhy.pressure.high": "आमदनी दे सापेक्ष मते सारे बिल जल्द गै देय होंदे न जां ओवरड्यू होंदे न।",
  "profileHub.scoreWhy.pressure.mid": "आमदनी दा इक ध्यान देने आह्ला हिस्सा आवर्ती बकाया च जंदा ऐ।",
  "profileHub.scoreWhy.pressure.low": "बिल इसलै आमदनी दे सापेक्ष प्रबंधनीय न।",
  "profileHub.scoreWhy.health.what": "बिल दे बोझ, भुगतान दी आदतें, बचत बफर, ते कर्ज दे रुझान गी इकट्ठा करदा ऐ।",
  "profileHub.scoreWhy.health.low": "बोझ, बफर, जां भुगतान दी स्थिरता च कमजोरी इसगी निचे खींच करदी ऐ।",
  "profileHub.scoreWhy.health.mid": "कुछ इलाकें च ठोस — किश आदतें जां बफर इसगी उप्पर चुक्की सकदे न।",
  "profileHub.scoreWhy.health.good": "कुल मिलाइयै आदतें ते बफर स्वस्थ दिक्खने गी मिलदियां न।",
  "profileHub.scoreWhy.runway.what": "महीने जेकर आमदनी रुकी गेई तां तुस जरूरी चीजें गी कवर करी सकदे ओ (तरल बचत + मुफ्त नकद)।",
  "profileHub.scoreWhy.runway.critical": "बडी पतली तकिया — इक आमदनी दा झटका सोखना मुश्किल होंदा।",
  "profileHub.scoreWhy.runway.thin": "आरामदायक 3-6 महीने दे रिजर्व थमां हेठ।",
  "profileHub.scoreWhy.runway.ok": "रनवे फिलहाल सुरक्षित रेंज च ऐ।",
  "profileHub.scoreWhy.flexibility.what": "मासिक बकाया तय करने दे बाद तुंदे कोल किन्ना कमरा ऐ।",
  "profileHub.scoreWhy.flexibility.low": "ज्यादातर आमदनी पैह् ले थमां गै आवर्ती बिलें लेई प्रतिबद्ध ऐ।",
  "profileHub.scoreWhy.flexibility.ok": "तुस हर म्हीने सार्थक मुफ्त नकदी बरकरार रखदे ओ।",
  "profileHub.scoreWhy.debt.what": "EMI ते मासिक आय दे हिस्से दे रूप च ऋण भुगतान।",
  "profileHub.scoreWhy.debt.high": "EMI भार भारी ऐ — नमें लोन कन्नै नकदी प्रवाह च तनाव होग।",
  "profileHub.scoreWhy.debt.ok": "कर्ज दा भुगतान इक प्रबंधनीय बैंड दे अंदर होंदा ऐ।",
  "profileHub.scoreWhy.lending.what": "उधार देने च तुसें दित्ते गेदे जां हासल कीते गेदे समें उप्पर वापसी गी ट्रैक करदा ऐ।",
  "profileHub.scoreWhy.lending.empty": "अजें तगर कोई उधार प्रविश्टी नेईं ऐ — इस स्कोर गी बनाने लेई सौदे जोड़ो ते वापसी लॉग करो।",
  "profileHub.scoreWhy.lending.low": "देरी कन्नै जां आंशिक वापसी कन्नै भरोसे च कमी आई।",
  "profileHub.scoreWhy.lending.ok": "चुकाने दा इतिहास भरोसेमंद लगदा ऐ।",
  "profileHub.scoreFix.pressure.clearOverdue": "पैह्ले ओवरड्यू बिल साफ करो — ओह् इस स्कोर गी सारें शा मता चोट पजांदे न।",
  "profileHub.scoreFix.pressure.trimSubscriptions": "सदस्यताएं ते वैकल्पिक EMIs दी समीक्षा करो जेह् ड़ी तुस रुकी सकदे ओ.",
  "profileHub.scoreFix.pressure.payOnTime": "दबाव स्थिर करने लेई इस महीने नियत तारीखें शा पैह्ले भुगतान करो।",
  "profileHub.scoreFix.runway.buildReserve": "हर तनखाह दिन इक निश्चित राशि गी तरल बचत च लेई जाओ।",
  "profileHub.scoreFix.runway.reduceBurn": "रनवे गी बधाने लेई गैर-जरूरी आवर्ती बिलें गी ट्रिम करो।",
  "profileHub.scoreFix.health.reduceBurden": "उच्च बोझ आह् ली प्रतिबद्धताएं गी घट्ट करना जां दुबारा शेड्यूल करना।",
  "profileHub.scoreFix.health.buildBuffer": "तरल बचत च 3-6 म्हीने दे खर्चे दा लक्ष्य बनाओ।",
  "profileHub.scoreFix.health.payOnTime": "भुगतान दी लकीर रखो — हर बिल भुगतान लॉग करो।",
  "profileHub.scoreFix.health.reduceDebt": "पैह्ले उच्चतम ब्याज दे बैलेंस पर चिप दूर करो।",
  "profileHub.scoreFix.health.keepGoing": "Keep current habits — you're on track.",
  "profileHub.scoreFix.health.general": "आमदनी, बिल, ते बचत लॉग करो तां जे स्कोर सटीक रौह्न।",
  "profileHub.scoreFix.flexibility.reduceBurden": "आवर्ती बकाया घट्ट करो जां जित्थें होई सकै EMI पर वार्ता करो।",
  "profileHub.scoreFix.flexibility.trackSpend": "लॉग चर खर्च तां मुफ्त नकद हकीकत कन्नै मेल खांदा ऐ।",
  "profileHub.scoreFix.debt.attackHighInterest": "क्रेडिट कार्ड ते उच्च दर आह् ले लोन गी वेतन क्रम च प्राथमिकता देओ।",
  "profileHub.scoreFix.debt.avoidNewEmi": "नमें EMIs थमां बचो, जदूं तकर ओवरलोड आमदनी दे ~35% थमां घट्ट नेईं होई जंदा।",
  "profileHub.scoreFix.lending.onTime": "सहमत तारीख पर उधार दी किश्तें गी इकट्ठा करना जां भुगतान करना।",
  "profileHub.scoreFix.lending.addDeals": "ट्रस्ट गी ट्रैक करना शुरू करने लेई उधार पृष्ठ थमां इक उधार प्रविश्टी जोड़ो।",
  "profileHub.scoreFix.lending.document": "आंशिक भुगतान रिकार्ड करो तां जे भरोसा हकीकत गी दर्शांदा ऐ।",
